import express, { Request, Response, NextFunction } from 'express';
const app = express();
const port = process.env.PORT || 3000;

const VALID_USERNAME = 'admin';
const VALID_PASSWORD = 'password';

interface AuthenticatedRequest extends Request {
  user?: { username: string };
}

function basicAuthMiddleware(req: AuthenticatedRequest, res: Response, next: NextFunction): void {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Basic ')) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }
  const base64 = authHeader.split(' ')[1];
  const decoded = Buffer.from(base64, 'base64').toString('utf-8');
  const [username, password] = decoded.split(':');
  if (username !== VALID_USERNAME || password !== VALID_PASSWORD) {
    res.status(401).json({ error: 'Invalid credentials' });
    return;
  }
  req.user = { username };
  next();
}

app.get('/public', (req: Request, res: Response) => {
  res.json({ message: 'Welcome to the public endpoint!' });
});

app.get('/secure', basicAuthMiddleware, (req: AuthenticatedRequest, res: Response) => {
  res.json({ message: 'You are authenticated!', user: req.user });
});

app.listen(port, () => console.log(`Server on port ${port}`));

