from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
import base64
import os

app = FastAPI()
port = int(os.getenv('PORT', 3000))

VALID_USERNAME = 'admin'
VALID_PASSWORD = 'password'

def basic_auth_middleware(request: Request):
    auth_header = request.headers.get('authorization')
    if not auth_header or not auth_header.startswith('Basic '):
        return JSONResponse(status_code=401, content={'error': 'Unauthorized'})
    base64_str = auth_header.split(' ')[1]
    decoded = base64.b64decode(base64_str).decode('utf-8')
    username, password = decoded.split(':', 1)
    if username != VALID_USERNAME or password != VALID_PASSWORD:
        return JSONResponse(status_code=401, content={'error': 'Invalid credentials'})
    request.state.user = {'username': username}
    return None

@app.get('/public')
def public():
    return {'message': 'Welcome to the public endpoint!'}

@app.get('/secure')
def secure(request: Request):
    err = basic_auth_middleware(request)
    if err:
        return err
    return {'message': 'You are authenticated!', 'user': request.state.user}

